/**
 * The invariant swept over the whole enumeration rather than sampled, which is affordable only now.
 *
 * Every construction path in the tree forwards to the one constructor as of the slice that collapsed
 * the last four raw object literals, so `ids` being present and frozen is one claim about one
 * expression instead of a claim repeated per producer. It is asserted per rule anyway, because the
 * severity half is read from the record and a rule whose answer drifted is named here rather than
 * found by whichever consumer notices first.
 *
 * `diagnostic` is reached with `ruleId` typed as the open `RuleId`, so `OwnedIds` resolves to its
 * optional case and one loop can carry both ownership answers without a cast. What that does not
 * prove is the refusal, which is why the negative cases live in
 * `ids-ownership-at-the-producer.test.ts` and are asked of the compiler instead.
 */
describe("every rule reaches a diagnostic whose payload is present and frozen", () => {
  it("carries a frozen ids and the rule's own severity, for every rule in the enumeration", () => {
    expect(RULE_IDS.length).toBeGreaterThan(100);

    for (const ruleId of RULE_IDS) {
      const built = diagnostic(ruleId, "$", "x", RULES[ruleId].ids === "always" ? ["seed"] : []);

      expect(Array.isArray(built.ids)).toBe(true);
      expect(Object.isFrozen(built.ids)).toBe(true);
      expect(Object.isFrozen(built)).toBe(true);
      expect(built.severity).toBe(RULES[ruleId].severity);
    }
  });

  it("answers the same at every other producer a test can reach without building a graph", () => {
    const built = [
      diag("track-id", "$", "no ids"),
      diag("motion-duplicate", "$", "named", ["hero/arm"]),
      ...batchFor(1, { kind: "deferred-in-batch", seeds: ["hero/arm"] }).diagnostics,
      ...batchFor(2, { kind: "deferred-in-flush", seeds: ["hero/arm"], scheduled: true })
        .diagnostics,
      ...buildGraphIR(observing("")).diagnostics,
    ];

    // The scan asserts it found its own subjects before it asserts anything about them.
    expect(built.length).toBeGreaterThan(4);
    for (const entry of built) {
      expect(Array.isArray(entry.ids)).toBe(true);
      expect(Object.isFrozen(entry.ids)).toBe(true);
      expect(Object.isFrozen(entry)).toBe(true);
    }
  });

  it("names the seeds a deferral deferred, so an always-naming rule says something", () => {
    const staged = batchFor(7, { kind: "deferred-in-batch", seeds: ["hero/arm"] });
    const flushed = batchFor(8, {
      kind: "deferred-in-flush",
      seeds: ["hero/arm", "caption/label"],
      scheduled: true,
    });

    expect(staged.diagnostics[0]?.ids).toEqual(["hero/arm"]);
    expect(flushed.diagnostics[0]?.ids).toEqual(["hero/arm", "caption/label"]);
  });
});

/**
 * Type identity, asserted rather than implied by a call's arity.
 *
 * The producer cases elsewhere prove that a payload is refused or required at a call site, which a
 * constructor with no payload parameter at all would also satisfy. These three pin what `OwnedIds`
 * actually answers, in both directions, so the ownership claim stops depending on any call. An edit
 * that widened the derivation back to an optional list for every rule fails here rather than staying
 * green against a tree whose call sites all pass an array. Not called, and exported so neither the
 * helper nor the constants are an unused local.
 */
type Exact<Answer, Expected> = [Answer] extends [Expected]
  ? [Expected] extends [Answer]
    ? true
    : false
  : false;

export function ownedIdsAnswersExactly(): readonly true[] {
  const idless: Exact<OwnedIds<"id-shape">, []> = true;
  const named: Exact<OwnedIds<"track-duplicate-id">, [ids: readonly string[]]> = true;
  const open: Exact<OwnedIds<RuleId>, [ids?: readonly string[]]> = true;
  return [idless, named, open];
}
